  if (value === null) return false;
  if (typeof value !== "object") return false;

  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}


function cloneValue(value: unknown): unknown {
  // Arrays are replaced wholesale, but their elements
  // may contain plain objects or nested arrays that
  // must be deep-copied so the result shares nothing
  // with the input.
  if (Array.isArray(value)) {
    return value.map((el) => cloneValue(el));
  }

  if (isPlainObject(value)) {
    const out: PlainObject = {};
    for (const key of Object.keys(value)) {
      if (SKIPPED_KEYS.has(key)) continue;
      out[key] = cloneValue(value[key]);
    }
    return out;
  }

  // Dates, Maps, class instances, functions, primitives –
  // keep by reference.
  return value;
}


export function deepMerge(
  ...objects: PlainObject[]
): PlainObject {
  const result: PlainObject = {};

  for (const obj of objects) {
    for (const key of Object.keys(obj)) {
      if (SKIPPED_KEYS.has(key)) continue;

      const incoming = obj[key];

      // undefined means "no opinion" – keep what we have.
      if (incoming === undefined) continue;

      const existing = result[key];

      // Recurse only when both sides are plain objects.
      // null, arrays, Dates, etc. replace outright.
      if (isPlainObject(incoming) && isPlainObject(existing)) {
        result[key] = deepMerge(existing, incoming);
        continue;
      }

      result[key] = cloneValue(incoming);
    }
  }

  return result;
}
